#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    int N;
    cin >> N;

    // 現在ログインしているかを表すフラグ：はじめはログインしていない
    bool logged_in = false;
    // 認証エラーを返された回数
    int unauthorized = 0;

    for (int i = 0; i < N; ++i) {
        string s;
        cin >> s;

        // ログイン操作なら、フラグを true にする
        if (s == "login") {
            logged_in = true;
        }
        // ログアウト操作なら、フラグを false にする
        if (s == "logout") {
            logged_in = false;
        }
        // ログインしていない状態で非公開ページにアクセスしようとしたとき、認証エラーを返された回数を増やす
        if (s == "private" && !logged_in) {
            unauthorized++;
        }
    }

    cout << unauthorized << endl;

    return 0;
}
